import 'package:flutter/material.dart';
import '../../core/api_client.dart';
import '../../core/theme.dart';
import '../auth/session_controller.dart';
class AddEmployeeScreen extends StatefulWidget{const AddEmployeeScreen({super.key,required this.session});final SessionController session;@override State<AddEmployeeScreen> createState()=>_AddEmployeeScreenState();}
class _AddEmployeeScreenState extends State<AddEmployeeScreen>{final name=TextEditingController(),phone=TextEditingController(),code=TextEditingController();String department='Production',shift='Morning';bool saving=false;Future<void> save()async{setState(()=>saving=true);try{await widget.session.createEmployee({'name':name.text.trim(),'phone':phone.text.trim(),'employeeCode':code.text.trim(),'department':department,'shiftName':shift,'joinDate':DateTime.now().toIso8601String().substring(0,10)});if(mounted)Navigator.pop(context,true);}on ApiException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}finally{if(mounted)setState(()=>saving=false);}}@override void dispose(){name.dispose();phone.dispose();code.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Add employee')),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Employee name')),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Phone')),TextField(controller:code,decoration:const InputDecoration(labelText:'Employee code')),DropdownButtonFormField(value:department,items:const [DropdownMenuItem(value:'Production',child:Text('Production')),DropdownMenuItem(value:'Quality',child:Text('Quality')),DropdownMenuItem(value:'Warehouse',child:Text('Warehouse'))],onChanged:(v)=>setState(()=>department=v!),decoration:const InputDecoration(labelText:'Department')),DropdownButtonFormField(value:shift,items:const [DropdownMenuItem(value:'Morning',child:Text('Morning')),DropdownMenuItem(value:'General',child:Text('General')),DropdownMenuItem(value:'Evening',child:Text('Evening'))],onChanged:(v)=>setState(()=>shift=v!),decoration:const InputDecoration(labelText:'Shift')),const SizedBox(height:22),FilledButton(onPressed:saving?null:save,style:FilledButton.styleFrom(backgroundColor:HRMateTheme.blue,padding:const EdgeInsets.symmetric(vertical:16)),child:Text(saving?'Saving…':'Create employee'))]));}
